/**
 * The knowledge writer over the generated training repository (decision 0029;
 * madarch-m38l.2). The repository is generated by examples/training-repository,
 * filled into a test store by the extract driver, and the writer's units run
 * with a scripted fake agent: no model. The fake answers as the answer key
 * says the product reads (its service, flow and doc items), reaching the graph
 * only through the writer's tools; the assertions judge what the core accepted
 * and wrote, never what the fake meant.
 *
 * Expected values come from the answer key and from the formats: the domains
 * the graph supports naming (payments and ordering), the statements and the
 * evidence behind them (the key's locations), the refusals (the format).
 *
 * The fill of the training repository takes minutes; the suite fills once.
 * MADARCH_WRITER_FIXTURE names a folder to keep the generated repository and
 * its filled store between runs while developing; CI fills fresh each time.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import { parse as parseYaml } from 'yaml';
import { createPGliteDatabaseOwner, type DatabaseOwner } from '../src/adapters/database-owner.js';
import { fillGraph } from '../src/extract/driver/index.js';
import { HISTORY_EXTRACTOR, OWNERS, TREE_EXTRACTORS } from '../src/extract/driver/extractors.js';
import { createGraphStore, type GraphStore } from '../src/graph/index.js';
import {
  DEFAULT_UNIT_BOUNDS, GraphView, UnitTools, WRITER_TOOLS, memorySink, runWriter, slugOf,
  type DomainDeclaration, type ToolAnswer, type UnitAgent, type UnitRequest, type UnitSpec, type WriterReport,
} from '../src/writer/index.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GENERATOR = path.join(ROOT, 'examples/training-repository/generate.mjs');

interface KeyItem {
  id: string;
  expectedWikiStatement: string;
  evidenceClass: string;
  location?: { path: string; symbol?: string; anchor?: string };
  locations?: { path: string; symbol?: string; anchor?: string }[];
}
const KEY = JSON.parse(readFileSync(path.join(ROOT, 'examples/training-repository/answer-key.json'), 'utf8')) as { snapshots: Record<string, string>; items: KeyItem[] };
const itemsOf = (pattern: RegExp): KeyItem[] => KEY.items.filter((item) => pattern.test(item.id));
const locationsOf = (item: KeyItem): { path: string; symbol?: string; anchor?: string }[] => item.locations ?? (item.location === undefined ? [] : [item.location]);

/** The domains the answer key's service, flow and doc items describe: the name a reader uses and the items behind it. */
const KEY_DOMAINS = [
  { slug: 'ordering', title: 'Ordering', service: 'orders', items: itemsOf(/^(service|flow)\.orders(\.|$)/), useCase: 'uc-1' },
  { slug: 'payments', title: 'Payments', service: 'payments', items: itemsOf(/^(service|flow)\.payments(\.|$)/), useCase: 'uc-2' },
];

let owner: DatabaseOwner;
let store: GraphStore;
let view: GraphView;
let repository: string;
let scratch: string;
let kept = false;

beforeAll(async () => {
  const fixture = process.env['MADARCH_WRITER_FIXTURE'];
  if (fixture !== undefined && fixture !== '') {
    kept = true;
    mkdirSync(fixture, { recursive: true });
    scratch = fixture;
  } else {
    scratch = mkdtempSync(path.join(tmpdir(), 'madarch-writer-'));
  }
  repository = path.join(scratch, 'repository');
  if (!existsSync(path.join(repository, '.git'))) execFileSync('node', [GENERATOR, repository], { stdio: 'ignore' });
  owner = createPGliteDatabaseOwner({ btreeGist: true, path: path.join(scratch, 'store') });
  store = createGraphStore(owner);
  await owner.ready;
  await store.createSchema();
  await fillGraph({ owner, store, repository, extractors: TREE_EXTRACTORS, owners: OWNERS, history: HISTORY_EXTRACTOR, snapshots: KEY.snapshots });
  view = await GraphView.open(owner, store);
}, 1_800_000);

afterAll(async () => {
  await owner?.close();
  if (!kept && scratch !== undefined) rmSync(scratch, { recursive: true, force: true });
}, 120_000);

// ---------------------------------------------------------------------------------------------
// The scripted fake agent
// ---------------------------------------------------------------------------------------------

/** A tool call whose answer must be what the unit's contract says; the fake stops the unit on any surprise. */
async function call(request: UnitRequest, tool: string, args: Record<string, unknown> = {}): Promise<ToolAnswer> {
  return await request.tools.call(tool, args);
}

/** The graph key of a place the key names: the symbol when the graph has it, otherwise the file. */
async function groundOf(request: UnitRequest, place: { path: string; symbol?: string }): Promise<string> {
  const file = `code.file:${place.path}`;
  const name = place.symbol?.replace(/^(export )?(async )?(func|function|class|interface|type|const)\s+(\([^)]*\)\s*)?/, '').match(/[A-Za-z_][A-Za-z0-9_]*/)?.[0];
  if (name === undefined) return file;
  const found = await call(request, 'find_nodes', { kind: 'code.symbol', text: `${place.path}#`, limit: 40 });
  const nodes = (found.answer as { nodes: { key: string; label: string }[] }).nodes;
  const hit = nodes.find((n) => n.label === name || n.key.endsWith(`#${name}`) || n.key.endsWith(`.${name}`));
  return hit !== undefined && !/\s/.test(hit.key) ? hit.key : file;
}

/** A statement of the key as grounded sentences: every sentence ends with the same footnote. */
function sentences(statement: string, label: string): string {
  const parts = statement.replace(/\s+/g, ' ').trim().split(/(?<=[.!?])\s+/);
  return parts.map((part) => `${/[.!?]$/.test(part) ? part : `${part}.`}[^${label}]`).join(' ');
}

async function evidenceFor(request: UnitRequest, item: KeyItem): Promise<string[]> {
  const grounds: string[] = [];
  for (const place of locationsOf(item)) {
    if (item.evidenceClass === 'document-fact') {
      const anchor = place.anchor === undefined ? undefined : slugOf(place.anchor.replace(/\.$/, ''));
      if (anchor !== undefined) grounds.push(`doc:${place.path}#${anchor}`);
    } else {
      grounds.push(await groundOf(request, place));
    }
  }
  return [...new Set(grounds)];
}

const footnote = (label: string, grounds: readonly string[]): string => `[^${label}]: ${grounds.map((g) => `[${g.replace(/^.*[:#/]/, '') || g}](madarch:${g})`).join(', ')}`;

interface Script {
  /** Pages the fake sends before the right one, to show a refusal reaches the agent. */
  readonly firstAttemptSpoiled?: boolean;
}

function productScript(script: Script = {}): (request: UnitRequest) => Promise<void> {
  return async (request) => {
    await call(request, 'overview');
    const vision = await call(request, 'read_file', { path: 'docs/vision.md' });
    expect((vision.answer as { sectionAnchors: string[] }).sectionAnchors).toContain('users');
    await call(request, 'read_file', { path: 'docs/requirements.md' });
    const services = await call(request, 'find_nodes', { kind: 'code.service' });
    const keys = (services.answer as { nodes: { key: string }[] }).nodes.map((n) => n.key);
    const statements = [...itemsOf(/^stack\.passport$/), ...itemsOf(/^doc\.vision$/), ...itemsOf(/^doc\.use-cases$/), ...itemsOf(/^architecture\.composition-root$/)];
    const body: string[] = ['## What the product is', ''];
    const notes: string[] = [];
    for (const [index, item] of statements.entries()) {
      const label = String(index + 1);
      body.push(sentences(item.expectedWikiStatement, label), '');
      notes.push(footnote(label, await evidenceFor(request, item)));
    }
    body.push('## Domains', '');
    for (const domain of KEY_DOMAINS) body.push(`- [${domain.title}](madarch:domain:${domain.slug}) is implemented by the [${domain.service} service](madarch:code.service:${domain.service}).[^${domain.slug}]`);
    for (const domain of KEY_DOMAINS) notes.push(footnote(domain.slug, [`code.service:${domain.service}`, `doc:docs/requirements.md#${domain.useCase}`]));
    body.push('', 'See also the services: ' + keys.map((k) => `[${k.replace('code.service:', '')}](madarch:${k})`).join(', ') + '.');
    const page = ['---', 'id: product:training-shop', 'kind: product', 'title: Training shop', 'relates:', ...keys.map((k) => `  - ${k}`), 'producer: agent', 'sources: [docs/vision.md, docs/requirements.md]', '---', '', ...body, '', ...notes].join('\n');
    const domains = KEY_DOMAINS.map((d) => ({ slug: d.slug, title: d.title, summary: `${d.title} is what the ${d.service} service does for a shopper.`, evidence: [`code.service:${d.service}`, `doc:docs/requirements.md#${d.useCase}`] }));
    if (script.firstAttemptSpoiled) {
      const refused = await call(request, 'write_page', { markdown: `${page}\n\nThe shop is fast.`, domains });
      expect(refused.isError).toBe(true);
    }
    const written = await call(request, 'write_page', { markdown: page, domains });
    expect(written.isError).toBe(false);
  };
}

function domainScript(spoil: boolean): (request: UnitRequest, domain: (typeof KEY_DOMAINS)[number]) => Promise<void> {
  return async (request, domain) => {
    await call(request, 'get_node', { key: `code.service:${domain.service}` });
    await call(request, 'neighbors', { key: `code.service:${domain.service}`, direction: 'out' });
    const body: string[] = [`## How ${domain.title.toLowerCase()} works`, ''];
    const notes: string[] = [];
    const relates = new Set<string>([`code.service:${domain.service}`]);
    for (const [index, item] of domain.items.entries()) {
      const label = String(index + 1);
      const grounds = await evidenceFor(request, item);
      grounds.forEach((g) => { if (g.startsWith('code.')) relates.add(g); });
      body.push(sentences(item.expectedWikiStatement, label), '');
      notes.push(footnote(label, grounds));
    }
    const related = KEY_DOMAINS.find((d) => d !== domain)!;
    body.push('## Requirements', '', `The use case of this domain is described in the requirements.[^uc]`, '', `See also [${related.title}](madarch:domain:${related.slug}).`);
    notes.push(footnote('uc', [`doc:docs/requirements.md#${domain.useCase}`]));
    const page = ['---', `id: domain:${domain.slug}`, 'kind: domain', `title: ${domain.title}`, 'relates:', ...[...relates].sort().map((k) => `  - ${k}`), 'producer: agent', 'sources: [docs/requirements.md]', '---', '', ...body, '', ...notes].join('\n');
    if (spoil) {
      // An ungrounded sentence and a ground that is not in the graph: both come back to the agent, and nothing is written.
      const refused = await call(request, 'write_page', { markdown: `${page}\n\nThe domain is very fast.\n\nIt is slow.[^spoiled]\n\n[^spoiled]: [nothing](madarch:code.symbol\u003aservices/${domain.service}/src/nope.ts#Nothing)` });
      expect(refused.isError).toBe(true);
      const rules = (refused.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule);
      expect(rules).toEqual(['ungrounded-statement', 'unresolved-ground']);
    }
    const written = await call(request, 'write_page', { markdown: page });
    expect(written.isError).toBe(false);
  };
}

interface Run {
  report: WriterReport;
  pages: Map<string, string>;
  prompts: Map<string, string>;
}

async function run(options: { spoilProduct?: boolean; spoilDomains?: boolean } = {}): Promise<Run> {
  const sink = memorySink();
  const prompts = new Map<string, string>();
  const product = productScript(options.spoilProduct === true ? { firstAttemptSpoiled: true } : {});
  const domain = domainScript(options.spoilDomains === true);
  const agent: UnitAgent = {
    run: async (request) => {
      prompts.set(request.id, request.prompt);
      if (request.id === 'product:training-shop') await product(request);
      else await domain(request, KEY_DOMAINS.find((d) => `domain:${d.slug}` === request.id)!);
    },
  };
  const report = await runWriter({ owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', agent, sink });
  return { report, pages: sink.pages, prompts };
}

// ---------------------------------------------------------------------------------------------
// What was written
// ---------------------------------------------------------------------------------------------

let first: Run;
let second: Run;

describe('the writer over the training repository', () => {
  beforeAll(async () => {
    first = await run({ spoilProduct: true, spoilDomains: true });
    second = await run();
  }, 600_000);

  test('runs one unit for the product and one per domain, in that order, and writes their three files', () => {
    expect(JSON.stringify([first.report.product.refusals, ...first.report.domains.map((d) => d.refusals)])).toBe('[[],[],[]]');
    expect(first.report.ok).toBe(true);
    expect(first.report.units).toBe(3);
    expect(first.report.product.unit).toBe('product:training-shop');
    expect(first.report.domains.map((d) => d.unit)).toEqual(['domain:ordering', 'domain:payments']);
    expect([...first.pages.keys()].sort()).toEqual(['docs/domains/ordering.md', 'docs/domains/payments.md', 'docs/product.md']);
    expect([...first.prompts.keys()]).toEqual(['product:training-shop', 'domain:ordering', 'domain:payments']);
  });

  test('stores the text files in the graph before any unit runs, and says what it left out', async () => {
    const content = first.report.content;
    expect(content.stored).toBeGreaterThan(50);
    // Binary or oversized files are named with a reason, never dropped silently.
    for (const skipped of content.skipped) expect(skipped.reason.length).toBeGreaterThan(0);
    const readme = readFileSync(path.join(repository, 'docs/vision.md'), 'utf8');
    expect(await view.fileText('docs/vision.md')).toBe(readme);
  });

  test('the product unit declares the domains the answer key describes: payments and ordering, each with evidence that resolves', async () => {
    const declared = first.report.product.domains;
    expect(declared.map((d: DomainDeclaration) => d.slug)).toEqual(['ordering', 'payments']);
    for (const domain of KEY_DOMAINS) {
      // The key's service, flow and doc items for the domain all point at code and documents the graph holds.
      expect(domain.items.length).toBeGreaterThan(0);
      for (const item of domain.items) {
        for (const place of locationsOf(item)) {
          expect(await view.graphKey(`code.file:${place.path}`)).toBe(true);
          expect(place.path.startsWith(`services/${domain.service}/`)).toBe(true);
        }
      }
      const declaration = declared.find((d: DomainDeclaration) => d.slug === domain.slug)!;
      for (const target of declaration.evidence) {
        if (target.startsWith('doc:')) {
          const [file, anchor] = target.slice(4).split('#');
          expect(await view.docSection(file!, anchor!)).toBe(true);
        } else {
          expect(await view.graphKey(target)).toBe(true);
        }
      }
    }
    const useCases = KEY.items.find((i) => i.id === 'doc.use-cases')!;
    for (const id of useCases.expectedWikiStatement.match(/UC-\d/g) ?? []) expect(await view.docSection('docs/requirements.md', id.toLowerCase())).toBe(true);
  });

  test('every page follows the format: front matter, then statements each ending in footnotes, then the footnotes', () => {
    for (const [file, markdown] of first.pages) {
      const match = /^---\n([^]*?)\n---\n\n([^]*)$/.exec(markdown);
      expect(match).not.toBeNull();
      const front = parseYaml(match![1]!) as Record<string, unknown>;
      expect(Object.keys(front)).toEqual(['id', 'kind', 'title', 'relates', 'producer', 'sources']);
      expect(front['producer']).toBe('agent');
      const isProduct = file === 'docs/product.md';
      expect(front['kind']).toBe(isProduct ? 'product' : 'domain');
      expect(front['id']).toBe(isProduct ? 'product:training-shop' : `domain:${path.basename(file, '.md')}`);
      expect(markdown.endsWith('\n')).toBe(true);
      const lines = match![2]!.split('\n');
      const definitions = lines.filter((l) => /^\[\^\d+\]: /.test(l));
      expect(definitions.map((l) => l.slice(0, l.indexOf(']:') + 1))).toEqual(definitions.map((_, i) => `[^${i + 1}]`));
      const text = lines.filter((l) => l.trim() !== '' && !/^\[\^\d+\]: /.test(l) && !l.startsWith('#') && !/^(- )?See also/.test(l) && !/^- \[[^\]]+\]\(madarch:[^)]+\)$/.test(l));
      expect(text.length).toBeGreaterThan(0);
      for (const line of text) {
        // Every statement line ends each of its sentences in footnote references.
        for (const sentence of line.replace(/^- /, '').split(/(?<=\])\s+(?=[A-Z])/)) expect(sentence).toMatch(/[.!?](\[\^\d+\])+$/);
      }
    }
  });

  test('every ground of every footnote resolves: a key the graph holds at the fill, or a section the document has', async () => {
    let grounds = 0;
    for (const markdown of first.pages.values()) {
      for (const definition of markdown.split('\n').filter((l) => /^\[\^\d+\]: /.test(l))) {
        for (const target of [...definition.matchAll(/\]\(madarch:([^)]+)\)/g)].map((m) => m[1]!)) {
          grounds += 1;
          if (target.startsWith('doc:')) {
            const [file, anchor] = target.slice(4).split('#');
            const text = readFileSync(path.join(repository, file!), 'utf8').toLowerCase();
            // Independent of the writer's own anchor index: the id appears in the document, or a heading or bold phrase slugs to the anchor.
            const slugs = [...text.matchAll(/^#+\s+(.*)$|\*\*([^*]+)\*\*/gm)].map((m) => slugOf((m[1] ?? m[2])!.replace(/\.$/, '')));
            expect(text.includes(anchor!) || slugs.includes(anchor!)).toBe(true);
          } else {
            const rows = (await owner.run((tx) => tx.query(`SELECT 1 FROM node_version WHERE properties->>'recordKey' = $1 AND recorded_to = 'infinity' LIMIT 1`, [target]))).rows;
            expect(rows.length).toBe(1);
          }
        }
      }
    }
    expect(grounds).toBeGreaterThan(20);
  });

  test('every entity link in the text is a key of the graph, a document section or a declared domain', async () => {
    const declared = new Set(first.report.product.domains.map((d: DomainDeclaration) => `domain:${d.slug}`));
    for (const markdown of first.pages.values()) {
      const body = markdown.split('\n').filter((l) => !/^\[\^\d+\]: /.test(l)).join('\n');
      for (const target of [...body.matchAll(/\]\(madarch:([^)]+)\)/g)].map((m) => m[1]!)) {
        if (target.startsWith('domain:')) expect(declared.has(target)).toBe(true);
        else if (target.startsWith('doc:')) expect(await view.docSection(target.slice(4).split('#')[0]!, target.split('#')[1]!)).toBe(true);
        else expect(await view.graphKey(target)).toBe(true);
      }
    }
  });

  test('a domain page names its own service and the code of the key\'s flow items among its relations and grounds', () => {
    for (const domain of KEY_DOMAINS) {
      const page = first.pages.get(`docs/domains/${domain.slug}.md`)!;
      const front = parseYaml(page.split('\n---\n')[0]!.slice(4)) as { relates: string[] };
      expect(front.relates).toContain(`code.service:${domain.service}`);
      const grounds = first.report.domains.find((d) => d.unit === `domain:${domain.slug}`)!.grounds;
      // The key's flow items for the domain are served by files under the service, so the page grounds code there.
      expect(grounds.some((g) => g.startsWith('code.') && g.includes(`services/${domain.service}/`))).toBe(true);
      expect(grounds.some((g) => g === `doc:docs/requirements.md#${domain.useCase}`)).toBe(true);
    }
  });

  test('a refusal comes back to the agent and the unit goes on: nothing was written until the page was right', () => {
    expect(first.report.product.writeAttempts).toBe(2);
    for (const domain of first.report.domains) expect(domain.writeAttempts).toBe(2);
    expect(second.report.product.writeAttempts).toBe(1);
  });

  test('the same graph, the same prompts and the same answers give the same files, byte for byte', () => {
    expect([...second.pages.entries()].sort()).toEqual([...first.pages.entries()].sort());
    expect([...second.prompts.entries()]).toEqual([...first.prompts.entries()]);
    expect(second.report.content.unchanged).toBe(true);
    expect(second.report.content.stored).toBe(first.report.content.stored);
  });

  test('the prompts hold the format and the graph, and no file content', () => {
    for (const prompt of first.prompts.values()) {
      expect(prompt).toContain('Every sentence that states something ends with a footnote');
      expect(prompt).toContain('code.service:orders');
      expect(prompt).not.toContain('CREATE TABLE');
      expect(prompt.length).toBeLessThan(20_000 * 4);
    }
    expect(first.prompts.get('domain:payments')!).toContain('Payments');
  });
});

// ---------------------------------------------------------------------------------------------
// The tools and their refusals
// ---------------------------------------------------------------------------------------------

describe('the unit tools', () => {
  const productSpec: UnitSpec = { kind: 'product', id: 'product:training-shop', path: 'docs/product.md', name: 'Training shop' };
  const domainSpec = (slug: string): UnitSpec => ({ kind: 'domain', id: `domain:${slug}`, path: `docs/domains/${slug}.md`, domain: { slug, title: slug, summary: 'x', evidence: ['code.service:payments'] } });
  const known: DomainDeclaration[] = [{ slug: 'payments', title: 'Payments', summary: 'Payments.', evidence: ['code.service:payments'] }];
  const header = (slug: string): string => `---\nid: domain:${slug}\nkind: domain\ntitle: Payments\nrelates:\n  - code.service:payments\nproducer: agent\nsources: []\n---\n\n`;
  const grounded = 'Payments run in the payments service.[^1]\n\n[^1]: [payments](madarch:code.service:payments)\n';

  function session(spec: UnitSpec = domainSpec('payments'), bounds = DEFAULT_UNIT_BOUNDS) {
    const sink = memorySink();
    return { sink, tools: new UnitTools(view, spec, sink, known, bounds) };
  }

  test('an agent has six tools and no way to reach the repository, a shell or the disk', () => {
    expect(WRITER_TOOLS.map((t) => t.name)).toEqual(['overview', 'find_nodes', 'get_node', 'neighbors', 'read_file', 'write_page']);
    const { tools } = session();
    expect(tools.tools.map((t) => t.name)).toEqual(['overview', 'find_nodes', 'get_node', 'neighbors', 'read_file', 'write_page']);
  });

  test('a file is read from the graph in bounded numbered lines, and a missing or unlisted file is an error', async () => {
    const { tools } = session();
    const answer = await tools.call('read_file', { path: 'docs/requirements.md', startLine: 3, endLine: 5 });
    expect(answer.isError).toBe(false);
    const text = readFileSync(path.join(repository, 'docs/requirements.md'), 'utf8').split('\n');
    const body = answer.answer as { text: string; startLine: number; endLine: number; totalLines: number; sectionAnchors: string[] };
    expect(body.text).toBe([3, 4, 5].map((n) => `${n}: ${text[n - 1]}`).join('\n'));
    expect(body.sectionAnchors).toContain('uc-1');
    const long = await tools.call('read_file', { path: 'docs/requirements.md', startLine: 1, endLine: 5000 });
    expect((long.answer as { text: string }).text.split('\n').length).toBeLessThanOrEqual(200);
    const missing = await tools.call('read_file', { path: '../../etc/passwd' });
    expect(missing.isError).toBe(true);
    expect((missing.answer as { error: { code: string } }).error.code).toBe('no-content');
    expect(tools.outcome().filesRead).toEqual(['docs/requirements.md']);
  });

  test('find_nodes pages in key order and node reads show the edges', async () => {
    const { tools } = session();
    const page = await tools.call('find_nodes', { kind: 'code.service' });
    expect((page.answer as { nodes: { key: string }[] }).nodes.map((n) => n.key)).toEqual(['code.service:checkout', 'code.service:orders', 'code.service:payments', 'code.service:promotions']);
    const some = await tools.call('find_nodes', { kind: 'code.symbol', limit: 3 });
    const { nodes, next } = some.answer as { nodes: { key: string }[]; next: string | null };
    expect(nodes).toHaveLength(3);
    expect(next).toBe(nodes[2]!.key);
    const following = await tools.call('find_nodes', { kind: 'code.symbol', limit: 3, after: next });
    expect((following.answer as { nodes: { key: string }[] }).nodes[0]!.key > nodes[2]!.key).toBe(true);
    const node = await tools.call('get_node', { key: 'code.service:payments' });
    expect((node.answer as { kind: string }).kind).toBe('code.service');
    expect((await tools.call('get_node', { key: 'code.service:nothing' })).isError).toBe(true);
    expect((await tools.call('neighbors', { key: 'code.service:payments', direction: 'sideways' })).isError).toBe(true);
  });

  test('a statement with no footnote is refused, and nothing is written', async () => {
    const { tools, sink } = session();
    const answer = await tools.call('write_page', { markdown: `${header('payments')}Payments run in the payments service.[^1] Refunds take thirty days.\n\n[^1]: [payments](madarch:code.service:payments)\n` });
    expect(answer.isError).toBe(true);
    const refused = (answer.answer as { refused: { rule: string; message: string }[]; attemptsLeft: number }).refused;
    expect(refused.map((r) => r.rule)).toEqual(['ungrounded-statement']);
    expect(refused[0]!.message).toContain('Refunds take thirty days.');
    expect((answer.answer as { attemptsLeft: number }).attemptsLeft).toBe(4);
    expect(sink.pages.size).toBe(0);
    expect(tools.outcome().status).toBe('failed');
  });

  test('a ground that does not resolve is refused, whether a key or a document section', async () => {
    const { tools, sink } = session();
    const key = await tools.call('write_page', { markdown: `${header('payments')}Payments run in the payments service.[^1]\n\n[^1]: [x](madarch:code.symbol\u003aservices/payments/src/missing.ts#Missing)\n` });
    expect((key.answer as { refused: { rule: string; message: string }[] }).refused.map((r) => r.rule)).toEqual(['unresolved-ground']);
    const section = await tools.call('write_page', { markdown: `${header('payments')}Payments run in the payments service.[^1]\n\n[^1]: [x](madarch:doc:docs/requirements.md#uc-99)\n` });
    expect((section.answer as { refused: { message: string }[] }).refused[0]!.message).toContain('has no section "uc-99"');
    expect(sink.pages.size).toBe(0);
  });

  test('a link outside the graph is refused, in the text and as a domain nobody declared', async () => {
    const { tools, sink } = session();
    const outside = await tools.call('write_page', { markdown: `${header('payments')}The [billing service](madarch:code.service:billing) charges cards.[^1]\n\n[^1]: [payments](madarch:code.service:payments)\n` });
    expect((outside.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule)).toEqual(['link-outside-graph']);
    const undeclared = await tools.call('write_page', { markdown: `${header('payments')}The [shipping domain](madarch:domain:shipping) is separate.[^1]\n\n[^1]: [payments](madarch:code.service:payments)\n` });
    expect((undeclared.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule)).toEqual(['link-outside-graph']);
    expect(sink.pages.size).toBe(0);
  });

  test('a page right the second time is written once, at the unit\'s own path, and a second write is refused', async () => {
    const { tools, sink } = session();
    expect((await tools.call('write_page', { markdown: `${header('payments')}Payments run.` })).isError).toBe(true);
    const written = await tools.call('write_page', { markdown: `${header('payments')}${grounded}` });
    expect(written.isError).toBe(false);
    expect([...sink.pages.keys()]).toEqual(['docs/domains/payments.md']);
    expect(tools.outcome()).toMatchObject({ status: 'written', writeAttempts: 2, refusals: [] });
    expect((await tools.call('write_page', { markdown: `${header('payments')}${grounded}` })).isError).toBe(true);
  });

  test('a page of another id is refused, so a unit cannot write another unit\'s page', async () => {
    const { tools, sink } = session(domainSpec('ordering'));
    const answer = await tools.call('write_page', { markdown: `${header('payments')}${grounded}` });
    expect((answer.answer as { refused: { message: string }[] }).refused[0]!.message).toContain('this page\'s id is "domain:ordering"');
    expect(sink.pages.size).toBe(0);
  });

  test('attempts are bounded: after the last refusal the unit has failed and nothing more is accepted', async () => {
    const { tools, sink } = session(domainSpec('payments'), { maxWriteAttempts: 2, maxCalls: 80 });
    expect((await tools.call('write_page', { markdown: `${header('payments')}Payments run.` })).isError).toBe(true);
    const last = await tools.call('write_page', { markdown: `${header('payments')}Payments run.` });
    expect((last.answer as { attemptsLeft: number; note: string }).attemptsLeft).toBe(0);
    expect(tools.finished).toBe(true);
    const after = await tools.call('write_page', { markdown: `${header('payments')}${grounded}` });
    expect((after.answer as { error: { code: string } }).error.code).toBe('no-attempts');
    expect(sink.pages.size).toBe(0);
    expect(tools.outcome()).toMatchObject({ status: 'failed', writeAttempts: 2 });
  });

  test('the number of tool calls is bounded too', async () => {
    const { tools } = session(domainSpec('payments'), { maxWriteAttempts: 5, maxCalls: 3 });
    for (let i = 0; i < 3; i += 1) expect((await tools.call('overview', {})).isError).toBe(false);
    const over = await tools.call('overview', {});
    expect((over.answer as { error: { code: string } }).error.code).toBe('call-limit');
    expect(tools.finished).toBe(true);
  });

  test('the product page declares its domains with evidence that must resolve, and links each of them', async () => {
    const page = (links: string): string => `---\nid: product:training-shop\nkind: product\ntitle: Training shop\nrelates: []\nproducer: agent\nsources: []\n---\n\n${links}\n\n[^1]: [payments](madarch:code.service:payments)\n`;
    const declaration = { slug: 'payments', title: 'Payments', summary: 'Payments.', evidence: ['code.service:payments'] };
    const missing = session(productSpec).tools;
    expect((await missing.call('write_page', { markdown: page('The shop takes payments.[^1]') })).isError).toBe(true);
    const unresolved = session(productSpec).tools;
    const bad = await unresolved.call('write_page', { markdown: page('The [payments](madarch:domain:payments) domain exists.[^1]'), domains: [{ ...declaration, evidence: ['code.service:nothing'] }] });
    expect(JSON.stringify(bad.answer)).toContain('does not resolve in the graph');
    const badSlug = await session(productSpec).tools.call('write_page', { markdown: page('The [payments](madarch:domain:payments) domain exists.[^1]'), domains: [{ ...declaration, slug: 'Pay Ments' }] });
    expect(JSON.stringify(badSlug.answer)).toContain('lower-case words');
    const unlinked = session(productSpec).tools;
    const notLinked = await unlinked.call('write_page', { markdown: page('The shop takes payments.[^1]'), domains: [declaration] });
    expect((notLinked.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule)).toEqual(['domain-not-linked']);
    const { tools, sink } = session(productSpec);
    const ok = await tools.call('write_page', { markdown: page('The [payments](madarch:domain:payments) domain exists.[^1]'), domains: [declaration] });
    expect(ok.isError).toBe(false);
    expect([...sink.pages.keys()]).toEqual(['docs/product.md']);
    expect(tools.outcome().domains.map((d) => d.slug)).toEqual(['payments']);
  });
});

describe('a run whose product unit fails', () => {
  test('writes nothing, runs no domain unit and reports the refusals', async () => {
    const sink = memorySink();
    const seen: string[] = [];
    const report = await runWriter({
      owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', sink,
      agent: { run: async (request: UnitRequest) => { seen.push(request.id); await request.tools.call('write_page', { markdown: 'no front matter' }); } },
    });
    expect(report.ok).toBe(false);
    expect(report.units).toBe(1);
    expect(seen).toEqual(['product:training-shop']);
    expect(report.product.status).toBe('failed');
    expect(report.product.refusals.map((r) => r.rule)).toEqual(['domains']);
    expect(sink.pages.size).toBe(0);
  });

  test('an agent that throws leaves the unit failed with the reason, and an agent that does nothing leaves it not written', async () => {
    const threw = await runWriter({ owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', sink: memorySink(), agent: { run: async () => { throw new Error('the agent process died'); } } });
    expect(threw.product.status).toBe('failed');
    expect(threw.product.refusals[0]!.message).toContain('the agent process died');
    const idle = await runWriter({ owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', sink: memorySink(), agent: { run: async () => undefined } });
    expect(idle.product.status).toBe('not-written');
    expect(idle.ok).toBe(false);
  });

  test('pages written by an earlier run that this run did not write are named, never deleted', async () => {
    const output = path.join(scratch, 'earlier-output');
    mkdirSync(path.join(output, 'docs/domains'), { recursive: true });
    writeFileSync(path.join(output, 'docs/domains/shipping.md'), 'an earlier page\n');
    const report = await runWriter({ owner, store, repository, output, productName: 'Training shop', sink: memorySink(), agent: { run: async () => undefined } });
    expect(report.stale).toEqual(['docs/domains/shipping.md']);
    expect(readFileSync(path.join(output, 'docs/domains/shipping.md'), 'utf8')).toBe('an earlier page\n');
  });
});
